"""Greeting banners."""
from vault.core import config


class User:
    def __init__(self, name: str):
        self.name = name


def banner(template: str, name: str) -> str:
    if '.__globals__' in template or 'config' in template or 'SECRET_KEY' in template:
        raise ValueError("Invalid characters detected in template string.")
    user = User(name)
    return template.format(user=user)
